mapper.select:
SELECT DISTINCT p.id, p.tenant_id, p.application_id, p.name, p.code, p.description, p.available, p.sort, p.version, p.is_delete, p.gmt_create, p.gmt_modify, p.create_user, p.modify_user FROM sys_permission p INNER JOIN sys_role_permission rp ON rp.permission_id = p.id AND rp.application_id = p.application_id WHERE p.is_delete = 0 AND p.available = 1 AND rp.role_id IN
#{roleId}
ORDER BY p.sort ASC, p.code ASC
